using System.Collections.ObjectModel;using System.Windows;using System.Windows.Controls;using SaarOSS.Rechnungsprogramm.Models;using SaarOSS.Rechnungsprogramm.Services;
namespace SaarOSS.Rechnungsprogramm.Views;
public partial class InvoicesView:UserControl
{
 private readonly InvoiceService _service=new();private readonly TaxProfileService _taxService=new();private readonly DocumentDesignService _designService=new();private readonly PaymentFooterService _paymentFooterService=new();private InvoiceStore _store=new();private InvoiceDraft _current=new();private ObservableCollection<InvoiceLine> _lines=new();private List<CustomerChoice> _customers=new();private bool _loading;
 public InvoicesView(){InitializeComponent();_current=NewDraftModel();LoadData();LoadForm(_current);}private void ApplyPaymentSummaries(){var ps=new PaymentService();var store=ps.Load();foreach(var invoice in _store.Drafts){if(invoice.Status=="Entwurf"||string.IsNullOrWhiteSpace(invoice.InvoiceNumber)){invoice.PaymentStatusDisplay="–";invoice.OpenAmountDisplay="–";continue;}var summary=ps.CalculateSummary(store,invoice.Id,invoice.GrossTotal,invoice.InvoiceDate.AddDays(invoice.PaymentTermDays),invoice.Status=="Storniert");invoice.PaymentStatusDisplay=summary.Status;invoice.OpenAmountDisplay=$"{summary.OpenAmount:N2} €";}}private InvoiceDraft NewDraftModel(){var p=_taxService.Load();var d=_designService.CreateSnapshot();var z=_paymentFooterService.CreateInvoiceSnapshot();return new(){TaxModeSnapshot=p.TaxMode,SmallBusinessNoticeSnapshot=p.IsSmallBusiness?p.SmallBusinessNotice:"",ShowLogoSnapshot=d.ShowLogo,LogoPngBase64Snapshot=d.LogoPngBase64,HeaderLine1Snapshot=d.HeaderLine1,HeaderLine2Snapshot=d.HeaderLine2,HeaderLine3Snapshot=d.HeaderLine3,HeaderLine4Snapshot=d.HeaderLine4,ShowBankDetailsSnapshot=z.ShowBankDetails,AccountHolderSnapshot=z.AccountHolder,BankNameSnapshot=z.BankName,IbanSnapshot=z.Iban,BicSnapshot=z.Bic,PaymentInstructionSnapshot=z.PaymentInstruction,PurposeTemplateSnapshot=z.PurposeTemplate,FooterLine1Snapshot=z.FooterLine1,FooterLine2Snapshot=z.FooterLine2,FooterLine3Snapshot=z.FooterLine3,FooterLine4Snapshot=z.FooterLine4,Lines=new(){new InvoiceLine{VatRate=p.IsSmallBusiness?0m:19m}}};}
 private void LoadData(){try{_store=_service.LoadInvoices();ApplyPaymentSummaries();_customers=_service.LoadCustomers();CustomerBox.ItemsSource=_customers;RefreshList();}catch(Exception ex){MessageBox.Show(ex.Message,"Rechnungen",MessageBoxButton.OK,MessageBoxImage.Error);}}
 private void RefreshList(){DraftList.ItemsSource=null;DraftList.ItemsSource=_store.Drafts.OrderByDescending(x=>x.UpdatedAt).ToList();DraftCountText.Text=$"{_store.Drafts.Count} Vorgänge";}
 private void LoadForm(InvoiceDraft d){_loading=true;_current=Clone(d);_lines=new(_current.Lines);LineGrid.ItemsSource=_lines;CustomerBox.SelectedItem=_customers.FirstOrDefault(x=>x.Id==_current.CustomerId);InvoiceDatePicker.SelectedDate=_current.InvoiceDate;ServiceDatePicker.SelectedDate=_current.ServiceDate;PaymentTermBox.Text=_current.PaymentTermDays.ToString();IntroBox.Text=_current.IntroText;ClosingBox.Text=_current.ClosingText;NoteBox.Text=_current.InternalNote;NumberText.Text=_current.DisplayNumber;EditorTitle.Text=_current.Status=="Entwurf"?(_current.DraftNumber==0?"Neue Rechnung":$"Entwurf {_current.DraftId}"):$"Rechnung {_current.InvoiceNumber}";UpdateTotals();UpdateDueDate();ApplyState();StatusText.Text="";_loading=false;}
 private void ApplyState(){var editable=_current.Status=="Entwurf";VatColumn.IsReadOnly=_current.IsSmallBusinessSnapshot;VatColumn.Header=_current.IsSmallBusinessSnapshot?"USt. (gesperrt)":"USt. %";if(_current.IsSmallBusinessSnapshot)foreach(var line in _lines)line.VatRate=0m;EditorPanel.IsEnabled=editable;SaveButton.Visibility=editable?Visibility.Visible:Visibility.Collapsed;DiscardButton.Visibility=editable?Visibility.Visible:Visibility.Collapsed;FinalizeButton.Visibility=editable&&_current.DraftNumber>0?Visibility.Visible:Visibility.Collapsed;CancelButton.Visibility=_current.Status=="Abgeschlossen"?Visibility.Visible:Visibility.Collapsed;PreviewButton.Visibility=_current.Status=="Abgeschlossen"||_current.Status=="Storniert"?Visibility.Visible:Visibility.Collapsed;StatusBannerText.Text=_current.Status=="Entwurf"?"Status: Entwurf – noch frei bearbeitbar":_current.Status=="Abgeschlossen"?$"Status: Abgeschlossen am {_current.FinalizedAt:dd.MM.yyyy HH:mm} – Inhalte geschützt":$"Status: Storniert am {_current.CancelledAt:dd.MM.yyyy HH:mm} – Grund: {_current.CancellationReason}";StatusBanner.Background=_current.Status=="Storniert"?new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(255,238,238)):new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(239,247,242));}
 private static InvoiceDraft Clone(InvoiceDraft x)=>new(){Id=x.Id,DraftNumber=x.DraftNumber,InvoiceNumber=x.InvoiceNumber,CustomerId=x.CustomerId,CustomerNumber=x.CustomerNumber,CustomerName=x.CustomerName,CustomerAddressSnapshot=x.CustomerAddressSnapshot,CompanySnapshot=x.CompanySnapshot,TaxModeSnapshot=x.TaxModeSnapshot,SmallBusinessNoticeSnapshot=x.SmallBusinessNoticeSnapshot,ShowLogoSnapshot=x.ShowLogoSnapshot,LogoPngBase64Snapshot=x.LogoPngBase64Snapshot,HeaderLine1Snapshot=x.HeaderLine1Snapshot,HeaderLine2Snapshot=x.HeaderLine2Snapshot,HeaderLine3Snapshot=x.HeaderLine3Snapshot,HeaderLine4Snapshot=x.HeaderLine4Snapshot,ShowBankDetailsSnapshot=x.ShowBankDetailsSnapshot,AccountHolderSnapshot=x.AccountHolderSnapshot,BankNameSnapshot=x.BankNameSnapshot,IbanSnapshot=x.IbanSnapshot,BicSnapshot=x.BicSnapshot,PaymentInstructionSnapshot=x.PaymentInstructionSnapshot,PurposeTemplateSnapshot=x.PurposeTemplateSnapshot,FooterLine1Snapshot=x.FooterLine1Snapshot,FooterLine2Snapshot=x.FooterLine2Snapshot,FooterLine3Snapshot=x.FooterLine3Snapshot,FooterLine4Snapshot=x.FooterLine4Snapshot,InvoiceDate=x.InvoiceDate,ServiceDate=x.ServiceDate,PaymentTermDays=x.PaymentTermDays,IntroText=x.IntroText,ClosingText=x.ClosingText,InternalNote=x.InternalNote,Status=x.Status,CancellationReason=x.CancellationReason,FinalizedAt=x.FinalizedAt,CancelledAt=x.CancelledAt,CreatedAt=x.CreatedAt,UpdatedAt=x.UpdatedAt,Lines=x.Lines.Select(y=>new InvoiceLine{Description=y.Description,Quantity=y.Quantity,Unit=y.Unit,UnitPrice=y.UnitPrice,VatRate=y.VatRate,DiscountPercent=y.DiscountPercent}).ToList()};
 private void NewDraft(object sender,RoutedEventArgs e){DraftList.SelectedItem=null;LoadForm(NewDraftModel());}private void DraftSelected(object sender,SelectionChangedEventArgs e){if(DraftList.SelectedItem is InvoiceDraft d)LoadForm(d);}private void CustomerChanged(object sender,SelectionChangedEventArgs e){if(!_loading&&CustomerBox.SelectedItem is CustomerChoice c&&c.PaymentTermDays.HasValue)PaymentTermBox.Text=c.PaymentTermDays.Value.ToString();}private void AddLine(object sender,RoutedEventArgs e){_lines.Add(new InvoiceLine{VatRate=_current.IsSmallBusinessSnapshot?0m:19m});UpdateTotals();}private void RemoveLine(object sender,RoutedEventArgs e){if(LineGrid.SelectedItem is InvoiceLine x&&_lines.Count>1)_lines.Remove(x);UpdateTotals();}private void LineChanged(object sender,EventArgs e){LineGrid.CommitEdit();UpdateTotals();}
 private void UpdateTotals(){if(_current.IsSmallBusinessSnapshot)foreach(var line in _lines)line.VatRate=0m;var net=_lines.Sum(x=>x.NetAmount);var vat=_lines.Sum(x=>x.VatAmount);NetText.Text=$"{net:N2} €";VatText.Text=$"{vat:N2} €";GrossText.Text=$"{net+vat:N2} €";LineGrid.Items.Refresh();}private void DateChanged(object sender,SelectionChangedEventArgs e){if(IsLoaded)UpdateDueDate();}private void PaymentChanged(object sender,TextChangedEventArgs e){if(IsLoaded)UpdateDueDate();}private void UpdateDueDate(){DueDateText.Text=InvoiceDatePicker.SelectedDate is DateTime d&&int.TryParse(PaymentTermBox.Text,out var days)&&days>=0&&days<=365?$"Fällig am: {d.AddDays(days):dd.MM.yyyy}":"Fälligkeit: Bitte Zahlungsziel prüfen";}
 private bool Validate(out int days){days=0;if(CustomerBox.SelectedItem is not CustomerChoice){MessageBox.Show("Bitte wählen Sie einen Kunden aus.","Eingabe prüfen",MessageBoxButton.OK,MessageBoxImage.Warning);return false;}if(!int.TryParse(PaymentTermBox.Text,out days)||days<0||days>365){MessageBox.Show("Das Zahlungsziel muss zwischen 0 und 365 Tagen liegen.","Eingabe prüfen",MessageBoxButton.OK,MessageBoxImage.Warning);return false;}if(_lines.Count==0||_lines.Any(x=>string.IsNullOrWhiteSpace(x.Description)||x.Quantity<=0||x.UnitPrice<0||x.VatRate<0||x.VatRate>100||x.DiscountPercent<0||x.DiscountPercent>100)){MessageBox.Show("Bitte prüfen Sie alle Rechnungspositionen.","Positionen prüfen",MessageBoxButton.OK,MessageBoxImage.Warning);return false;}return true;}
 private void ReadForm(int days){var c=(CustomerChoice)CustomerBox.SelectedItem;_current.CustomerId=c.Id;_current.CustomerNumber=c.CustomerNumber;_current.CustomerName=c.DisplayName;_current.InvoiceDate=InvoiceDatePicker.SelectedDate??DateTime.Today;_current.ServiceDate=ServiceDatePicker.SelectedDate??_current.InvoiceDate;_current.PaymentTermDays=days;_current.IntroText=IntroBox.Text.Trim();_current.ClosingText=ClosingBox.Text.Trim();_current.InternalNote=NoteBox.Text.Trim();if(_current.IsSmallBusinessSnapshot)foreach(var line in _lines)line.VatRate=0m;_current.Lines=_lines.ToList();}
 private void SaveDraft(object sender,RoutedEventArgs e){LineGrid.CommitEdit();UpdateTotals();if(!Validate(out var days))return;SaveButton.IsEnabled=false;try{ReadForm(days);_service.SaveDraft(_store,_current);RefreshList();LoadForm(_current);StatusText.Text="✓ Entwurf sicher gespeichert";}catch(Exception ex){MessageBox.Show(ex.Message,"Speicherfehler",MessageBoxButton.OK,MessageBoxImage.Error);}finally{SaveButton.IsEnabled=true;}}
 private void Discard(object sender,RoutedEventArgs e){var saved=_store.Drafts.FirstOrDefault(x=>x.Id==_current.Id);LoadForm(saved??NewDraftModel());}
 private void Finalize(object sender,RoutedEventArgs e){LineGrid.CommitEdit();if(!Validate(out var days))return;ReadForm(days);var preview=_service.PreviewInvoiceNumber(_store,_current.InvoiceDate);var c=(CustomerChoice)CustomerBox.SelectedItem;var check=new InvoiceFinalizationCheckWindow(_current,c.AddressSnapshot,preview){Owner=Window.GetWindow(this)};if(check.ShowDialog()!=true)return;try{_service.FinalizeInvoice(_store,_current,_service.LoadCompanySnapshot(),c.AddressSnapshot);RefreshList();LoadForm(_current);StatusText.Text="✓ Rechnung abgeschlossen und geschützt";}catch(Exception ex){MessageBox.Show(ex.Message,"Abschlussfehler",MessageBoxButton.OK,MessageBoxImage.Error);}}
 private void Cancel(object sender,RoutedEventArgs e){var dialog=new CancellationReasonDialog{Owner=Window.GetWindow(this)};if(dialog.ShowDialog()!=true)return;if(MessageBox.Show("Die Rechnung wird als storniert gekennzeichnet und bleibt erhalten. Fortfahren?","Stornierung",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{_service.CancelInvoice(_store,_current,dialog.Reason);RefreshList();LoadForm(_current);StatusText.Text="✓ Rechnung storniert";}catch(Exception ex){MessageBox.Show(ex.Message,"Stornierung",MessageBoxButton.OK,MessageBoxImage.Error);}}
 private void Preview(object sender,RoutedEventArgs e){if(_current.Status=="Entwurf"){MessageBox.Show("Eine Vorschau ist nach dem Rechnungsabschluss verfügbar.","Rechnungsvorschau",MessageBoxButton.OK,MessageBoxImage.Information);return;}new InvoicePreviewWindow(Clone(_current)){Owner=Window.GetWindow(this)}.ShowDialog();}
}
